const tidyPath = 'server/test/acceptance/cardTidy.test.js';
const kbText = readFileSync(kbPath, 'utf8');
const kb = JSON.parse(kbText);
assert.equal(JSON.stringify(kb, null, 2) + '\\n', kbText);
const pinText = readFileSync(pinPath, 'utf8');
const pinStart = pinText.indexOf('export const TWO_LINE = ') + 'export const TWO_LINE = '.length;
const pinEnd = pinText.indexOf('\\n};', pinStart) + 2;
const pins = JSON.parse(pinText.slice(pinStart, pinEnd));
assert.equal(JSON.stringify(pins, null, 2), pinText.slice(pinStart, pinEnd));
const byId = new Map(kb.entries.map(e => [e.id, e]));
const order = {
  salmon_wild_vs_farmed: [0, 2, 3, 4, 1],
  label_nonGMO_vs_organic: [0, 4, 1, 2],
  canned_fish_choosing: [2, 4, 3, 0, 1],
  label_wild_vs_farm_raised: [0, 4, 3, 1, 2],
  tortillas: [0, 3, 2, 1],
  oat_milk: [0, 2, 1],
  canned_tuna: [0, 2, 1],
  smoked_salmon: [0, 4, 3, 1, 2],
  almond_milk: [0, 1, 4, 2, 3],
  soy_milk: [0, 4, 3, 1],
  cooking_oils: [0, 2, 3, 4, 1],
  canned_coconut_milk: [0, 3, 2, 1],
  canned_soup: [0, 4, 1],
  tortilla_chips: [0, 1, 2, 4, 3],
  popcorn: [0, 2, 1, 4],
};
const tips = Object.fromEntries(Object.entries(order).map(([id, indexes]) => [id, indexes.map(i => byId.get(id).buying_tips[i])]));
const shrimp = byId.get('shrimp_imported_vs_domestic').buying_tips;
tips.shrimp_imported_vs_domestic = [
  shrimp[0],
  shrimp[3],
  shrimp[2],
  'Uniform size and a flawless look point to pond-raised; wild shrimp come in a wide range of sizes.',
  '‘Fresh’ at the case is nearly always thawed, so frozen raw is the same shrimp. Ask the case if it is dry, since wet shrimp holds extra water.',
];
tips.sugars = [
  'More than half of granulated sugar sold comes from bioengineered sugar beets.',
  'Plain “sugar” names no crop, so choose certified organic first; organic must come from non-GMO plants. Non-GMO Project Verified is a close second.',
  'Pick light or dark brown sugar; dark carries more molasses.',
];
const watch = {
  soy_milk: [
    'FDA counts only fortified soy in the dairy group, yet fortifying adds vitamins and minerals, each another ingredient.',
    'Soy lecithin and soy protein come from the same soybeans. A QR code or phone number may lead to the bioengineered disclosure.',
    'Dairy shoppers can read the Milk card.',
  ],
  canned_soup: [
    '“No salt added” is not “sodium free”; the soup can still carry sodium.',
    'BPA-free is the maker’s word. EWG’s survey found makers define it as they wish. Makers that dropped BPA did not disclose the lining that replaced it.',
    'Store cans cool and dry, between 50 °F and 70 °F, with the oldest in front. Wipe the lid before opening, and move opened soup to a covered container in the refrigerator.',
  ],
};
assert.equal(Object.keys(tips).length, 17);
for (const [id, buying_tips] of Object.entries(tips)) {
  assert.ok(buying_tips.every(s => typeof s === 'string' && s.length));
  assert.deepEqual(pins[id].buying_tips, byId.get(id).buying_tips);
  byId.get(id).buying_tips = buying_tips;
  pins[id].buying_tips = buying_tips;
}
for (const [id, watch_out] of Object.entries(watch)) {
  assert.deepEqual(pins[id].watch_out, byId.get(id).watch_out);
  byId.get(id).watch_out = watch_out;
  pins[id].watch_out = watch_out;
}
const tidyText = readFileSync(tidyPath, 'utf8');
const oldKeeper = '  popcorn: [/never bioengineered/i, /CSPI/i, /avocado/i, /coconut oil/i, /brown paper bag/i, /canola/i],';
const newKeeper = '  popcorn: [/never bioengineered/i, /CSPI/i, /avocado/i, /coconut oil/i, /canola/i],';
assert.equal(tidyText.split(oldKeeper).length, 2);
writeFileSync(kbPath, JSON.stringify(kb, null, 2) + '\\n');
writeFileSync(pinPath, pinText.slice(0, pinStart) + JSON.stringify(pins, null, 2) + pinText.slice(pinEnd));
writeFileSync(tidyPath, tidyText.replace(oldKeeper, newKeeper));
console.log('Updated 17 buying_tips arrays, 2 watch_out arrays, their static pins, and the popcorn keeper.');
NODE"

