import assert from 'node:assert/strict';
import fs from 'node:fs';
import { syncBuiltinESMExports } from 'node:module';
import { resolve } from 'node:path';
const outputPath = resolve('lib/doLines.json');
const before = fs.readFileSync(outputPath);
let writes = 0;
const originalWrite = fs.writeFileSync;
fs.writeFileSync = (path, data, encoding) => {
  assert.equal(resolve(String(path)), outputPath, 'generator output path');
  assert.deepEqual(Buffer.from(data, encoding), before, 'generated do lines must be byte-identical');
  writes++;
};
syncBuiltinESMExports();
try {
  await import('./scripts/buildDoLines.js');
  assert.equal(writes, 1, 'generator must produce one output');
} finally {
  fs.writeFileSync = originalWrite;
  syncBuiltinESMExports();
}
assert.deepEqual(fs.readFileSync(outputPath), before);
console.log('Read-only generation: all 182 do lines match byte-for-byte; no file was written.');
NODE"

